-- Multi-select conversion for OSI Layer(s) mapping questions (2026-11-14).
-- Anki-NF-1113: TCP/IP Application Layer = Application, Presentation, Session (choose 3).
-- Anki-NF-1116: TCP/IP Link Layer = Data Link, Physical (choose 2).
-- Options are all 7 OSI layers; no irrelevant distractors.

UPDATE questions SET question = 'OSI Model _____ Layer(s) = TCP/IP Application Layer (Choose three answers)', options = '[\"A. Application\",\"B. Presentation\",\"C. Session\",\"D. Transport\",\"E. Network\",\"F. Data Link\",\"G. Physical\"]', correct_option = '[0,1,2]', explanation = '<div class=\"explanation-rich-content\">\n<div class=\"expl-card concept-card\"><div class=\"section-title-concept\">📌 Core Concept: OSI vs TCP/IP - Application Layer Mapping</div><p>The TCP (Transmission Control Protocol)/IP (Internet Protocol) model has only four layers, so it collapses the top three OSI layers (Application, Presentation, Session) into a single TCP/IP Application layer.</p></div>\n<div class=\"expl-card correct-card\"><h4 class=\"section-title-correct\">✓ Why the Correct Answers are Correct:</h4><ul><li><span class=\"opt-tag correct\">Option A</span> <strong>Application</strong>: Application is OSI Layer 7, the top layer, and it maps to the TCP/IP Application layer.</li><li><span class=\"opt-tag correct\">Option B</span> <strong>Presentation</strong>: Presentation is OSI Layer 6, and it maps to the TCP/IP Application layer.</li><li><span class=\"opt-tag correct\">Option C</span> <strong>Session</strong>: Session is OSI Layer 5, and it maps to the TCP/IP Application layer.</li></ul></div>\n<div class=\"expl-card incorrect-card\"><h4 class=\"section-title-incorrect\">✗ Why Other Options are Incorrect:</h4><ul><li><span class=\"opt-tag wrong\">Option D</span> <strong>Transport</strong>: Transport is OSI Layer 4, which maps to the TCP/IP Transport layer. Not to the Application layer.</li><li><span class=\"opt-tag wrong\">Option E</span> <strong>Network</strong>: Network is OSI Layer 3, which maps to the TCP/IP Internet layer. Not to the Application layer.</li><li><span class=\"opt-tag wrong\">Option F</span> <strong>Data Link</strong>: Data Link is OSI Layer 2, which maps to the TCP/IP Link layer. Not to the Application layer.</li><li><span class=\"opt-tag wrong\">Option G</span> <strong>Physical</strong>: Physical is OSI Layer 1, which maps to the TCP/IP Link layer. Not to the Application layer.</li></ul></div>\n<div class=\"expl-card tip-card\"><h4 class=\"section-title-tip\">💡 CCNA Exam Tip:</h4><p>Memorise the mapping: OSI 7+6+5 = TCP/IP Application, OSI 4 = Transport, OSI 3 = Internet, OSI 2+1 = Link.</p></div>\n<div class=\"expl-card concept-card\"><div class=\"section-title-concept\">📌 Source: Anki Flashcards - Network Fundamentals (CCNA / Day 03 Flashcards - OSI Model, TCP/IP Suite)</div></div>\n</div>' WHERE question_no = 'Anki-NF-1113';

UPDATE questions SET question = 'OSI Model _____ Layer(s) = TCP/IP Link Layer (Choose two answers)', options = '[\"A. Application\",\"B. Presentation\",\"C. Session\",\"D. Transport\",\"E. Network\",\"F. Data Link\",\"G. Physical\"]', correct_option = '[5,6]', explanation = '<div class=\"explanation-rich-content\">\n<div class=\"expl-card concept-card\"><div class=\"section-title-concept\">📌 Core Concept: OSI vs TCP/IP - Link Layer Mapping</div><p>The TCP (Transmission Control Protocol)/IP (Internet Protocol) Link layer (also called Network Access) corresponds to the bottom two OSI layers: Data Link (Layer 2) and Physical (Layer 1). Together they handle local delivery and the physical medium.</p></div>\n<div class=\"expl-card correct-card\"><h4 class=\"section-title-correct\">✓ Why the Correct Answers are Correct:</h4><ul><li><span class=\"opt-tag correct\">Option F</span> <strong>Data Link</strong>: Data Link is OSI Layer 2 and it maps to the TCP/IP Link layer.</li><li><span class=\"opt-tag correct\">Option G</span> <strong>Physical</strong>: Physical is OSI Layer 1 and it maps to the TCP/IP Link layer.</li></ul></div>\n<div class=\"expl-card incorrect-card\"><h4 class=\"section-title-incorrect\">✗ Why Other Options are Incorrect:</h4><ul><li><span class=\"opt-tag wrong\">Option A</span> <strong>Application</strong>: Application is OSI Layer 7, which maps to the TCP/IP Application layer. Not to the Link layer.</li><li><span class=\"opt-tag wrong\">Option B</span> <strong>Presentation</strong>: Presentation is OSI Layer 6, which maps to the TCP/IP Application layer. Not to the Link layer.</li><li><span class=\"opt-tag wrong\">Option C</span> <strong>Session</strong>: Session is OSI Layer 5, which maps to the TCP/IP Application layer. Not to the Link layer.</li><li><span class=\"opt-tag wrong\">Option D</span> <strong>Transport</strong>: Transport is OSI Layer 4, which maps to the TCP/IP Transport layer. Not to the Link layer.</li><li><span class=\"opt-tag wrong\">Option E</span> <strong>Network</strong>: Network is OSI Layer 3, which maps to the TCP/IP Internet layer. Not to the Link layer.</li></ul></div>\n<div class=\"expl-card tip-card\"><h4 class=\"section-title-tip\">💡 CCNA Exam Tip:</h4><p>Memorise the mapping: OSI 7+6+5 = TCP/IP Application, OSI 4 = Transport, OSI 3 = Internet, OSI 2+1 = Link.</p></div>\n<div class=\"expl-card concept-card\"><div class=\"section-title-concept\">📌 Source: Anki Flashcards - Network Fundamentals (CCNA / Day 03 Flashcards - OSI Model, TCP/IP Suite)</div></div>\n</div>' WHERE question_no = 'Anki-NF-1116';

